import{_ as t,o,c as a,a2 as s}from"./chunks/framework.ecJ-2P1q.js";const g=JSON.parse('{"title":"Widget Embedding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/widget-embedding.md","filePath":"guide/widget-embedding.md"}'),r={name:"guide/widget-embedding.md"};function i(n,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="widget-embedding" tabindex="-1">Widget Embedding <a class="header-anchor" href="#widget-embedding" aria-label="Permalink to &quot;Widget Embedding&quot;">​</a></h1><p>The embeddable chat widget drops a small floating chat window onto any web page, backed by one of your Aerini workflows. This page covers what the workflow needs to look like, how to add the widget to a page, how a message actually travels from the visitor&#39;s browser to your workflow and back, and the tradeoffs worth knowing before you put this on a page other people can reach. It assumes you&#39;ve read <a href="./credentials">Credentials</a> and <a href="./security">Security</a>; most of what makes the widget safe or risky to expose is the token and secret model those two pages already cover, applied here to one specific feature.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>The widget only works with a workflow shaped a specific way, already running in the background:</p><ul><li>The workflow&#39;s trigger has to be a <strong>Webhook</strong> node, not Schedule, Manual, or a plugin trigger. See <a href="./nodes#webhook">Nodes Reference §Webhook</a> for its fields.</li><li>The workflow needs an <strong>Output</strong> node, so the widget has something to show back to the visitor. See <a href="./nodes#output">Nodes Reference §Output</a>.</li><li>The workflow has to already be running as a background job: either <strong>Schedule Run</strong> in the desktop app, or started through <code>aerini-server</code>&#39;s <code>api</code> mode (<code>POST /api/scheduler/:id/start</code>). A workflow that&#39;s saved but not started shows an error the moment someone opens the widget; see <a href="#what-each-error-means">What each error means</a> below.</li></ul><p>The widget itself is only served by <code>aerini-server</code> running in <strong><code>api</code> mode</strong>. <code>aerini-server serve</code>, the single-workflow mode covered in <a href="./background-runs#beyond-the-desktop-app">Background Runs §Beyond the desktop app</a>, doesn&#39;t have it. Setting up <code>api</code> mode is covered in <a href="./../operations/server-deploy">Server Deployment</a>.</p><h2 id="embedding-the-script" tabindex="-1">Embedding the script <a class="header-anchor" href="#embedding-the-script" aria-label="Permalink to &quot;Embedding the script&quot;">​</a></h2><p>Add one script tag to the page you want the widget on:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://your-server.example.com/aerini-widget.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://your-server.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-workflow-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wf_abc123&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a short-lived token from /api/widget/wf_abc123/mint-token — see below&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a read-scoped token, ACL&#39;d to this one workflow&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>That&#39;s the whole setup. The script injects a floating chat bubble and its window on its own; there&#39;s no separate element to add or function to call. <code>data-secret</code> can also be the Webhook node&#39;s raw secret directly — see <a href="#how-a-message-reaches-the-workflow">How a message reaches the workflow</a> for the tradeoff between the two before picking one.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Required</th><th>What it does</th></tr></thead><tbody><tr><td><code>data-server</code></td><td>Yes</td><td>Base URL of your <code>aerini-server</code> instance.</td></tr><tr><td><code>data-workflow-id</code></td><td>Yes</td><td>The workflow&#39;s ID.</td></tr><tr><td><code>data-secret</code></td><td>Yes</td><td>Either the Webhook node&#39;s configured <code>secret</code> field, or a short-lived signed token minted from it. See <a href="#how-a-message-reaches-the-workflow">How a message reaches the workflow</a> — read that before deciding which one to put here.</td></tr><tr><td><code>data-token</code></td><td>No, but replies won&#39;t arrive without one</td><td>A token used only to read this workflow&#39;s reply. See <a href="#getting-the-reply-back">Getting the reply back</a>.</td></tr><tr><td><code>data-session-id</code></td><td>No</td><td>A stable ID grouping one visitor&#39;s messages, and used server-side to keep one visitor&#39;s replies from reaching another visitor&#39;s browser. See <a href="#getting-the-reply-back">Getting the reply back</a>. Generated with the browser&#39;s Web Crypto API and kept in local storage if you leave it out; a browser without Web Crypto can&#39;t generate one, so the widget doesn&#39;t start there unless you set this.</td></tr><tr><td><code>data-allow-images</code></td><td>No</td><td><code>&quot;true&quot;</code> by default. Set <code>&quot;false&quot;</code> to always render replies as text, even when the Output node&#39;s value is image data.</td></tr><tr><td><code>data-max-length</code></td><td>No</td><td>Character limit on a single message, enforced before it&#39;s sent. Default 2000.</td></tr><tr><td><code>data-theme</code></td><td>No</td><td><code>&quot;light&quot;</code> (default) or <code>&quot;dark&quot;</code>.</td></tr></tbody></table><p>Leave out any of the three required attributes and the widget doesn&#39;t appear at all. It logs an error to the browser console and stops before adding anything to the page.</p><h2 id="how-a-message-reaches-the-workflow" tabindex="-1">How a message reaches the workflow <a class="header-anchor" href="#how-a-message-reaches-the-workflow" aria-label="Permalink to &quot;How a message reaches the workflow&quot;">​</a></h2><p>A widget embedded on a page hosted somewhere else can&#39;t call the Webhook node&#39;s listener directly. That listener always binds to <code>127.0.0.1</code>, the server&#39;s own loopback address, the same restriction <a href="./nodes#webhook">Nodes Reference §Webhook</a> and <a href="./background-runs#how-webhook-behaves-in-the-background">Background Runs</a> already describe: nothing outside the machine running Aerini can reach it without something in front of it.</p><p>The widget&#39;s relay endpoint, <code>POST /api/widget/:workflow_id/trigger</code>, is that something. It runs on the same server as the rest of the API, the one the browser already reached to load the widget script in the first place, and forwards the request over that server&#39;s own loopback interface to the port the workflow&#39;s Webhook trigger is actually bound to right now.</p><p>This relay endpoint doesn&#39;t require a bearer token the way every other API route does. A widget sitting in a third-party page&#39;s source can&#39;t hold a real admin or write token without handing it to every visitor, so it&#39;s authenticated a different way: whatever&#39;s in <code>data-secret</code>, sent as the <code>x-webhook-secret</code> header, the same header a webhook provider like Stripe or GitHub would send. The relay checks it with the same function the Webhook listener uses, accepting either form below, and forwards it only if it is valid; the listener then validates it again. A Webhook node with no secret configured is refused, because the relay is reachable by anyone who can load your page: set a secret on the Webhook node before using the widget.</p><p><strong>Two ways to fill in <code>data-secret</code>, with a real security difference between them:</strong></p><ul><li><p><strong>The raw secret, directly.</strong> Simplest to set up — just paste the Webhook node&#39;s <code>secret</code> field into the script tag — but it&#39;s visible to anyone who views the page source, forever, until you rotate it. Fine for something low-stakes or internal. Not recommended for a public production page.</p></li><li><p><strong>A short-lived signed token, recommended for production.</strong> Your own backend — which already has the real secret, since it&#39;s the same one you&#39;d otherwise paste directly — exchanges it for a token that expires on its own, server-side, immediately before rendering the page:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-server.example.com/api/widget/wf_abc123/mint-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;secret&quot;: &quot;&lt;the Webhook node secret&gt;&quot;, &quot;ttl_secs&quot;: 300}&#39;</span></span></code></pre></div><p>This returns <code>{&quot;token&quot;: &quot;awh1.&lt;expiry&gt;.&lt;signature&gt;&quot;, &quot;expires_at&quot;: &quot;...&quot;, &quot;ttl_secs&quot;: 300}</code>. Put that <code>token</code> value in <code>data-secret</code> instead of the raw secret — the widget doesn&#39;t need to know the difference, it just forwards whatever&#39;s there. <strong>Call <code>mint-token</code> from your server when rendering the page, never from the visitor&#39;s browser</strong> (the server enforces this for browsers: it never grants any origin, <code>--allow-origin</code> included, cross-origin access to <code>mint-token</code>) — the raw secret has to stay server-side for this to mean anything; if the browser calls it directly you&#39;ve just moved the same standing exposure to a different endpoint. A captured token still lets its holder trigger the workflow, exactly like the raw secret does, but only until <code>expires_at</code> — after that it&#39;s dead regardless of who has it, which the raw secret never is on its own. <code>ttl_secs</code> is clamped to a 24-hour ceiling server-side no matter what you request; pick the shortest value that comfortably outlives one page view.</p></li></ul><p>Neither form cryptographically signs the message body, so even a token in active use doesn&#39;t stop a captured request from being replayed verbatim until it expires. If you need that too, see <a href="./nodes#webhook">Nodes Reference §Webhook</a>&#39;s note on verifying a platform HMAC header downstream — the same mechanism applies here.</p><p><code>mint-token</code>, like <code>trigger</code>, is rate-limited per caller IP: it&#39;s a secret-guessing oracle in the same way the trigger endpoint is (a wrong secret gets a 401, a right one a 200), so treat 429s from it the same way — back off, don&#39;t retry in a tight loop.</p><h2 id="getting-the-reply-back" tabindex="-1">Getting the reply back <a class="header-anchor" href="#getting-the-reply-back" aria-label="Permalink to &quot;Getting the reply back&quot;">​</a></h2><p>The trigger call&#39;s own response is not the workflow&#39;s answer, only an acknowledgement that the request reached the Webhook listener. The actual reply arrives separately, as an event on the server&#39;s live event stream, Server-Sent Events (SSE): a plain HTTP connection the server keeps open and pushes updates through. The widget opens that connection at <code>GET /api/events</code> on page load and waits for a <code>scheduler-status</code> event carrying this workflow&#39;s result once the run finishes.</p><p>Reading that stream needs a bearer token, same as any other authenticated route, which is what <code>data-token</code> is for. Without one, the widget can still send messages, but every one of them times out on the browser side after 30 seconds with no way to show a reply, and a banner in the chat window tells the visitor replies aren&#39;t available.</p><p>Create that token from an account with <code>admin</code> scope, scoped to this one workflow in the same call; see <a href="./security#hardening-a-server-deployment">Security §Hardening a server deployment</a> for what scope means here:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-server.example.com/api/tokens</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;your admin token&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;label&quot;: &quot;widget-reader&quot;, &quot;scopes&quot;: [&quot;read&quot;], &quot;workflow_ids&quot;: [&quot;wf_abc123&quot;]}&#39;</span></span></code></pre></div><p>Save the token from that response, it&#39;s only shown once. <code>workflow_ids</code> restricts it to exactly the workflows listed, granted atomically in this same call — leave it out (or empty) and a <code>read</code>-scoped token can see every workflow&#39;s events on the server, not just the one you&#39;re embedding. There&#39;s no reason to leave it out for a widget token.</p><p><code>data-token</code> is embedded in page HTML the same as <code>data-secret</code> is, so every visitor of the page shares that one token. On its own that would mean one visitor&#39;s browser receives every other visitor&#39;s replies too — the SSE stream is per-workflow, not per-visitor. <code>data-session-id</code> is what prevents that: the widget includes it on every connection, and the server only forwards a reply to the connection whose session matches the one that sent it. This only filters the widget&#39;s own rendering path — it doesn&#39;t change what the token itself is scoped to, so treat <code>data-token</code> as &quot;can read this workflow&#39;s results,&quot; not &quot;can read this visitor&#39;s results,&quot; when deciding how it&#39;s stored and how often it&#39;s rotated.</p><h2 id="allowing-your-origin-through-cors" tabindex="-1">Allowing your origin through CORS <a class="header-anchor" href="#allowing-your-origin-through-cors" aria-label="Permalink to &quot;Allowing your origin through CORS&quot;">​</a></h2><p>Local origins, <code>http://localhost</code> and <code>http://127.0.0.1</code> on any port, can always call the server. Anything else, meaning the actual domain your embedding page is served from, needs to be added explicitly with <code>--allow-origin</code>, one of <code>aerini-server api</code>&#39;s startup flags:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aerini-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-site.example.com</span></span></code></pre></div><p>Cross-Origin Resource Sharing (CORS) is the browser&#39;s own check on whether a page is allowed to call a server it wasn&#39;t loaded from. It&#39;s enforced by the browser, not by Aerini, but the server still has to explicitly say yes for the browser to allow it through. Skip this flag and the widget&#39;s trigger call fails before it ever reaches Aerini&#39;s server code: the browser blocks the request itself, and the widget falls back to showing whatever generic message the browser&#39;s own failed network call carried, something like &quot;Failed to fetch,&quot; worded differently depending on the browser. See <a href="./../operations/server-deploy">Server Deployment</a> for the rest of <code>api</code> mode&#39;s startup flags.</p><h2 id="what-each-error-means" tabindex="-1">What each error means <a class="header-anchor" href="#what-each-error-means" aria-label="Permalink to &quot;What each error means&quot;">​</a></h2><p>Everything below assumes CORS already allowed the request through and Aerini&#39;s server actually received it. A request the browser blocks for CORS never reaches that far; see the note above for what the widget shows instead in that case.</p><table tabindex="0"><thead><tr><th>What the widget shows</th><th>What actually happened</th></tr></thead><tbody><tr><td>&quot;workflow is not scheduled: start it first&quot;</td><td>No background job exists yet for this workflow ID at all. Start it with Schedule Run in the desktop app, or <code>POST /api/scheduler/:id/start</code> in <code>api</code> mode.</td></tr><tr><td>&quot;workflow is not running (status: stopped)&quot; (or <code>paused</code>, <code>done</code>, <code>error</code>)</td><td>A job exists but isn&#39;t currently active. Same fix: start or restart it.</td></tr><tr><td>&quot;workflow&#39;s trigger is &#39;...&#39;, not Webhook: the embeddable widget only works with a Webhook-triggered workflow&quot;</td><td>The workflow&#39;s trigger is something other than Webhook. The message names which one (Interval, Cron, Once, Manual, or Plugin); only Webhook works with the widget.</td></tr><tr><td>&quot;workflow definition not found&quot;</td><td>The scheduled job exists but its saved workflow definition doesn&#39;t — most often a workflow deleted without stopping its job first. Stop the job, or point the widget at a workflow ID that still exists.</td></tr><tr><td>&quot;this workflow contains a Shell Command, Code, or Database node — the public widget relay refuses to trigger it, regardless of the server&#39;s --allow-shell/--allow-code/--allow-database flags&quot;</td><td>The target workflow contains one of those node types. The relay refuses unconditionally, before it ever reaches the workflow&#39;s listener — see <a href="#security-tradeoffs-to-know-before-you-embed-this">Security tradeoffs</a>.</td></tr><tr><td>&quot;internal server error&quot;</td><td>The server hit a database or internal failure while looking up the workflow. The widget gets no detail; the cause is in the server log.</td></tr><tr><td>&quot;could not reach the workflow&#39;s webhook listener, it may have just stopped&quot;</td><td>The job looked active a moment ago, but the loopback call to it failed anyway, most often because it stopped in between. Try again.</td></tr><tr><td>&quot;this Webhook node has no secret configured — the public widget relay will not trigger a workflow that anyone could start; set a secret on the Webhook node&quot;</td><td>The Webhook node&#39;s <code>secret</code> field is empty. Set one, and use it (or a token minted from it) as <code>data-secret</code>.</td></tr><tr><td>&quot;the secret did not match the Webhook node&#39;s configured secret&quot;</td><td><code>data-secret</code> doesn&#39;t match the Webhook node&#39;s <code>secret</code> field, or a signed token in <code>data-secret</code> has expired or was minted for a different workflow&#39;s secret.</td></tr><tr><td>&quot;the request path or HTTP method did not match the Webhook node&#39;s configuration&quot;</td><td>The Webhook node&#39;s <code>path</code> doesn&#39;t match what the relay is calling, or its <code>method</code> isn&#39;t <code>POST</code> or <code>ANY</code>. The widget only ever sends POST.</td></tr><tr><td>&quot;message too large&quot;</td><td>The message body exceeded the Webhook listener&#39;s own 1 MB cap, far above <code>data-max-length</code>&#39;s default, but reachable if you raised that default a lot.</td></tr><tr><td>&quot;the webhook listener rejected the request&quot;</td><td>A catch-all for anything else the listener refused: a malformed request, or one that took too long partway through. Usually clears on retry.</td></tr><tr><td>429 Too Many Requests, from <code>trigger</code> or <code>mint-token</code></td><td>The per-IP or per-workflow rate limit on that endpoint was hit. See <a href="#security-tradeoffs-to-know-before-you-embed-this">Security tradeoffs</a>. Back off; don&#39;t retry immediately.</td></tr></tbody></table><p>The first six come straight from the relay endpoint itself; the rest are the relay translating whatever the Webhook listener told it. Either way, the widget shows the message as an error bubble in the chat window, not a silent failure.</p><h2 id="security-tradeoffs-to-know-before-you-embed-this" tabindex="-1">Security tradeoffs to know before you embed this <a class="header-anchor" href="#security-tradeoffs-to-know-before-you-embed-this" aria-label="Permalink to &quot;Security tradeoffs to know before you embed this&quot;">​</a></h2><p><code>data-secret</code> and <code>data-token</code> both sit in plain HTML on whatever page you embed the widget on. Anyone who views that page&#39;s source has both. There&#39;s no way to keep a value truly secret once it ships to a browser — that&#39;s inherent to any credential embedded in client-side code, not particular to Aerini. What that means in practice, and what&#39;s done about each:</p><ul><li><strong>Direct triggering / replay.</strong> Anyone with the page source can call <code>trigger</code> directly, without going through the widget UI, and can replay a captured request exactly as sent — neither the raw secret nor a signed token cryptographically binds to the request body. Two things bound this rather than eliminate it: use a signed token (see <a href="#how-a-message-reaches-the-workflow">How a message reaches the workflow</a>) so a captured credential expires instead of working forever, and rely on the rate limits below to cap how much damage a captured credential — expired or not — can do in the meantime. <code>trigger</code> is limited to 20 requests/minute per caller IP and 60/minute per workflow (whichever is hit first applies; only requests carrying a valid secret or token count against the per-workflow limit, so callers with a wrong secret cannot use up the allowance your visitors share); <code>mint-token</code> is limited to 10/minute per caller IP, tighter because a wrong guess there costs the caller nothing but a 401, the same shape of risk as a login form. Both return <code>429 Too Many Requests</code> once hit. If your workflow does something that costs real money or resources per run (an LLM call, a paid API, a database write), the rate limit is a ceiling on that cost from this endpoint, not a guarantee — size it against what you&#39;d tolerate at the limit, not against expected normal traffic.</li><li><strong>Reply token scope.</strong> Scope the reply token to this one workflow — <code>workflow_ids</code> in the <code>POST /api/tokens</code> call above, done in the same request as creation now, not a separate step to remember. An unrestricted token in page source can read every workflow&#39;s run results on the server, not just this one.</li><li><strong>Cross-visitor reply leakage.</strong> Fixed as of this doc: <code>data-session-id</code>, described above, keeps one visitor&#39;s SSE connection from receiving another visitor&#39;s reply. Set it explicitly (rather than relying on the auto-generated one) only if you have a reason to — e.g. syncing it with your own site&#39;s session — since the auto-generated one already does the job.</li><li><strong>Dangerous nodes.</strong> Shell Command, Code, and Database nodes are disabled server-wide by default — <code>aerini-server api</code> refuses to execute any of them unless started with <code>--allow-shell</code>, <code>--allow-code</code>, or <code>--allow-database</code> respectively (see <a href="./../operations/server-deploy">Server Deployment</a>). Those flags are server-wide, not per-workflow: enabling one for an unrelated internal workflow would otherwise also unlock that node type for anything else the same server process runs. The widget relay closes that gap for itself specifically: <code>POST /api/widget/:workflow_id/trigger</code> checks the target workflow&#39;s own nodes before relaying anything, and refuses with <code>403</code> if it contains a Shell Command, Code, or Database node — regardless of which <code>--allow-*</code> flags happen to be set, and before the request ever reaches the workflow&#39;s listener. This check is scoped to the public, unauthenticated widget relay; a dangerous-node workflow triggered through an authenticated Bearer-token route is still governed only by the <code>--allow-*</code> flags, same as ever. See <a href="./security#dangerous-nodes">Security §Dangerous nodes</a> for what the confirmation dialog looks like for an interactive run — it never appears for a background-triggered one, widget included, the same as any other scheduled or webhook fire; the <code>--allow-*</code> flags (and, for this one route, the check above) are the actual enforcement, the dialog is a separate, interactive-only nicety.</li></ul><p>Treat a publicly embedded widget the same way you&#39;d treat any other public form: rate-limited and time-boxed by the above, but still something an anonymous visitor can set off. Fine for something you&#39;d be comfortable with anyone triggering; the mitigations above narrow the blast radius, they don&#39;t remove the fact that it&#39;s public.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chat-panel">Chat Panel</a>, for the desktop-only equivalent of this feature — same workflow shape, no secret or token needed since it never leaves the machine</li><li><a href="./nodes#webhook">Nodes Reference</a>, for the Webhook node&#39;s full field table and the Output node&#39;s fields</li><li><a href="./background-runs#how-webhook-behaves-in-the-background">Background Runs</a>, for what it means for a Webhook-triggered workflow to be running in the background</li><li><a href="./credentials">Credentials</a>, for the encrypted credential store, a separate mechanism from the secret and token this page covers</li><li><a href="./security#hardening-a-server-deployment">Security</a>, for scoped tokens, <code>--allow-origin</code>, and the rest of hardening an <code>aerini-server api</code> deployment</li><li><a href="./../operations/server-deploy">Server Deployment</a>, for the rest of running <code>aerini-server api</code> itself</li></ul>`,41)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
